#!/bin/bash
set -u
send() { tmux send-keys -t "$1" -l "$2"; tmux send-keys -t "$1" C-m; }
echo "$(date -u +%FT%TZ): Khiem: window reopened, all six resumed, BUDGET 6, ready-first order." >> /root/qc/RATE-LIMIT-LOG.md

ALL="Khiem, $(date -u +%H:%M) UTC: window reopened, account live. RESUME. Read your own STATUS file, then /root/qc/GATE-V2.md 3.6 (rulings) and 3.4, then SESSIONS.md 1.19. Run 6 agents now (BUDGET 6, ramp per 1.14). Bias: GENUINELY CLEARED, ZIPPABLE TASKS FIRST. Order your queue by distance to a complete GATE.md: (1) tasks whose GATE.md already exists, finish them through probes and zip; (2) built zips needing re-gate; (3) everything else. Per task the full gate: K sentence on xlsx deliverables; existing scans plus Z scans; blind Opus CR with maps a to f; Fable refuter only if the CR passes; fixes per 3.3 with _before/ and FIX-LOG; oracle 1.0, no-cache probe recorded, echo under 0.3 via /root/qc/tools/judge_emulate.py; per task, apply the rewardkit ==0.1.7 pin and the must-pass strip yourself with the Z tools (rewardkit_pin.py and muststrip_scan.py, --apply on YOUR claimed task only; Z does not edit other owners' task dirs); zip via stage_and_zip.sh only when 3.4 holds. STATUS every task boundary with the count of GATE.md complete and zips built. First zip ETA in STATUS within 15 minutes."

send main "$ALL Main first job before any zip: the stage_and_zip.sh actuator (GATE-V2 3.4 last paragraph): exit non-zero on any fail and on warn/skip/error in the gate-relevant set, print every non-pass cell, environment_size_budget advisory, 10 MB threshold. Then your 14 returned tasks, nearest to done first (22-5-0 and 12-8-0 were mid-fix), into out/main/resubmit/, in tens. 54-2-0 went to DataOS alone as batch 3 at 13:35; its verdict is the gate test."
send E "$ALL E: 54-2-0 is submitted (batch 3), do not touch it. Your 20 remaining zips: start with 73-4-0, 91-3-0, 91-2-0, 94-8-0, 75-4-0 (GATE.md started), then the rest of your 13, then your 8 batch-2 zips."
send D "$ALL D: your 25 batch-2 zips are unsubmitted and yours to re-gate. Start with 10-4-0, 46-1-0, 10-5-0, 16-1-0, 1-5-0, 25-7-0, 52-2-0, 8-4-0 (GATE.md started). Restore Sources names in 42-3-0 and 42-9-0 when you reach them."
send B "$ALL B: start with 29-5-0, 26-4-0, 33-8-0, 33-6-0 (applied, GATE.md started), then 80-6-0, 38-1-0, then the rest of your 36. Restore Sources names in 42-7-0 when you reach it."
send F "$ALL F: start with 5-2-0 and 41-3-0 (GATE.md started), then your 3 resubmits in out/F/resubmit/, then rebuild 36-5-0 (batch 2, zip missing from out/F/), then the rest."
send Z "$ALL Z: finish the scan extensions with 2 agents max and stop building after that; the other 4 agents go to your own tasks: 13-7-0 re-gate, 5-3-0 resubmit audit into out/Z/resubmit/, 94-7-0, 2-4-0, 70-4-0. Do NOT run rewardkit_pin.py --apply or muststrip --apply on other owners' tasks; they apply it themselves per task. Make sure both tools support --apply <task> and say so in STATUS-Z within 10 minutes."
echo sent
